<style>
  /* Import Clash Display Font */
  @import url('https://fonts.cdnfonts.com/css/clash-display');

  /* ===== SECTION WRAPPER ===== */
  .opal-roll-section {
      
    position: relative;
    background: transparent;
    overflow: hidden;
  }
.call-pill {
    margin-left: 30px;
    display: inline-flex;
    align-items: center;
    gap: 8px;
    background: #ffa300;
    color: #000 !important;
    font-weight: 700 !important;
    font-size: 18px;
    text-transform: uppercase;
    padding: 10px 22px;
    border-radius: 999px;
    white-space: nowrap;
    text-decoration: none;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
     font-family: 'Prompt';
}
  /* ===== TRACK (TILTED STRIP) ===== */
  .opal-roll-track {
    display: flex;
    width: max-content;

    /* animation */
    animation: scrollLeft 35s linear infinite;

    /* tilt */
    transform: rotate(-3deg);
    transform-origin: center;

    /* design - updated with blue (#073875) */
    background: black;
    padding: 22px 0;
  }

  /* ===== CONTENT ===== */
  .opal-roll-content {
    display: flex;
    gap: 40px;
    padding-right: 60px;
  }

  /* ===== TEXT STYLE ===== */
  .opal-roll-content span {
    font-family: 'Prompt', sans-serif;
    font-size: 22px;
    font-weight: 600;
    letter-spacing: 2px;
    text-transform: uppercase;
    color: #FBEAE5;
    white-space: nowrap;
    position: relative;
  }

  /* separator icon - updated with maroon (#750707) */
  .opal-roll-content span::after {
    content: "|";
    margin-left: 50px;
    color: #750707;
    font-size: 25px;
    color: #fff;
}
  /* remove last separator */
  .opal-roll-content span:last-child::after {
    content: "";
  }

  /* ===== ANIMATION ===== */
  @keyframes scrollLeft {
    0% {
      transform: translateX(0);
    }
    100% {
      transform: translateX(-50%);
    }
  }

  /* ===== HOVER PAUSE ===== */
  .opal-roll-section:hover .opal-roll-track {
    animation-play-state: paused;
  }

  /* ===== RESPONSIVE ===== */
  @media (max-width: 768px) {
    .opal-roll-track {
      animation-duration: 40s;
      transform: rotate(-2deg);
      padding: 18px 0;
    }

    .opal-roll-content {
      gap: 30px;
      padding-right: 40px;
    }

    .opal-roll-content span {
      font-size: 16px;
      letter-spacing: 1px;
    }
    
    .opal-roll-content span::after {
      margin-left: 30px;
      font-size: 28px;
    }
  }

  /* Extra small screens */
  @media (max-width: 480px) {
    .opal-roll-content span {
      font-size: 12px;
    }
    
    .opal-roll-content {
      gap: 20px;
      padding-right: 25px;
    }
    
    .opal-roll-content span::after {
      margin-left: 20px;
      font-size: 10px;
    }
    .call-pill {
    font-size: 12px !important;
    padding: 2px 12px;
}
  }
</style>

<script>
  // Optional: dynamically adjust speed based on screen width
  const track = document.querySelector('.opal-roll-track');

  function adjustSpeed() {
    if (window.innerWidth < 768) {
      track.style.animationDuration = "25s";
    } else {
      track.style.animationDuration = "35s";
    }
  }

  if (track) {
    adjustSpeed();
    window.addEventListener('resize', adjustSpeed);
  }
